//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::nat::shiftl`; the
//! native twin is `benches/native/Bench/NatShiftl.lean`.
//! Nat words on both sides (2n+1); every result stays below 2^63; native tests its exponent limit
//! (2^32) first, which the crate lifts (LB-11, LB-12): its word path is the word helper

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::nat;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match nat::shiftl(nat_arg(nat_box(x >> 40)), nat_arg(nat_box((x >> 4) & 31))) {
                Ok(v) => nat_unbox(nat_res(v)),
                Err(p) => end(p),
            },
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
